  return {
    disparos: 0, falhas: 0,
    disparos_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    respostas: 0,
    respostas_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    enc_advisor: 0, enc_parcerias: 0,
    calls_marcadas: 0, marcadas_log: 0, marcadas_reuniao: 0,
    calls_realizadas: 0, calls_noshow: 0,
    calls_hoje: 0, calls_a_frente: 0
  };
