const reunioesPorLead = {};
for (const r of reunioesLista) {
  const canal = canalPorApp(r.origem);
  if (!canal) continue;
  const chaves = [];
  if (r.mailing_id) chaves.push('m' + r.mailing_id);
  const tel = String(r.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  const marcos = [tsLocal(r.criado_em), tsLocal(r.data_hora_agendada)].filter(t => t !== null);
  for (const c of chaves) (reunioesPorLead[c] = reunioesPorLead[c] || []).push({ canal, marcos });
}
