        const d = Math.abs(m - ts);
        if (d < menor) { menor = d; melhor = r.canal; }
      }
    }
  }
  return melhor;
}
function canalDaCall(row, ts) {
  const chaves = [];
  if (row.mailing_id !== null && row.mailing_id !== undefined && row.mailing_id !== '') chaves.push('m' + row.mailing_id);
  const tel = String(row.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  return canalPorReuniao(chaves, ts)
      || (chaves.length ? canalDoLeadEm(chaves[0], ts) : null)
      || canalPorMidiaNome(row.midia_nome)
      || 'outros';
}

for (const row of $('agenda').all().map(i => i.json).filter(r => r && r.evento)) {
  const dia = row.dia ? diaLocal(String(row.dia).slice(0, 10) + 'T12:00:00Z') : null;
  const b = R[canalDaCall(row, dia !== null ? dia : Date.now())] || R.outros;
  if (row.evento === 'agendada_hoje') { b.calls_hoje++; continue; }
  if (row.evento === 'agendada_frente') { b.calls_a_frente++; continue; }
  if (!noPeriodo(dia)) continue;
  if (row.evento === 'marcada') {
    const ch = chavesDe(row.mailing_id, row.telefone);
    if (!jaMarcada(ch, dia)) { registraMarcada(ch, dia); b.calls_marcadas++; b.marcadas_log++; }
