  const dia = diaLocal(r.criado_em);
  if (!noPeriodo(dia)) continue;
  const ch = chavesDe(r.mailing_id, r.telefone);
  if (!ch.length || jaMarcada(ch, dia)) continue;
  registraMarcada(ch, dia);
  const canal = canalPorApp(r.origem) || canalDoLeadEm(ch[0], tsLocal(r.criado_em)) || 'outros';
  const b = R[canal] || R.outros;
  b.calls_marcadas++;
